use anyhow::{Result,ensure};
use sarv_quote::{domain::State,store::Store,export};
use std::{fs,path::PathBuf};
fn main()->Result<()> {let args:Vec<_>=std::env::args().collect();let root=PathBuf::from(&args[1]);fs::create_dir_all(&root)?;
 for(name,source)in[("actual-quotes-manual","docs/assets/accounting-m3/migration/current-v4.json"),("actual-detailed-opening","docs/assets/accounting-m3/restore/core-v4.json"),("actual-zero-initialization","docs/assets/accounting-m3/review/final4-main/zero-backup.json")]{
 let dir=root.join(name);fs::create_dir(&dir)?;let envelope:serde_json::Value=serde_json::from_slice(&fs::read(source)?)?;let prior:State=serde_json::from_value(envelope["state"].clone())?;ensure!(prior.schema==4&&prior.accounting.procurement.is_empty(),"actual retained v4source");prior.validate()?;let old=serde_json::to_value(&prior)?;let csv=prior.quotes.iter().map(export::csv_bytes).collect::<Result<Vec<_>>>()?;
 let db=rusqlite::Connection::open(dir.join("sarv.sqlite3"))?;db.execute_batch("CREATE TABLE state(id INTEGER PRIMARY KEY CHECK(id=1),generation INTEGER NOT NULL,payload TEXT NOT NULL)")?;db.execute("INSERT INTO state VALUES(1,71,?1)",[serde_json::to_string(&prior)?])?;drop(db);
 let store=Store::open(&dir)?;ensure!(store.state.schema==5&&store.local_generation()==72,"actual4→5 exactlyonegeneration");let mut expected=old;expected["schema"]=5.into();ensure!(serde_json::to_value(&store.state)?==expected,"allquotes/manual/opening/effect/alias/policy/dateexactpreserve");ensure!(csv==store.state.quotes.iter().map(export::csv_bytes).collect::<Result<Vec<_>>>()?,"quote CSVbyteexact");
 let recovery=fs::read_dir(&dir)?.map(|x|x.unwrap().path()).filter(|p|p.file_name().unwrap().to_string_lossy().starts_with("before-schema5-")).collect::<Vec<_>>();ensure!(recovery.len()==1,"one original v4recovery");let raw:serde_json::Value=serde_json::from_slice(&fs::read(&recovery[0])?)?;ensure!(raw["format"]=="sarv-accounting-backup-v4"&&raw["state"]==envelope["state"],"exact untouched source v4recovery");ensure!(serde_json::to_value(Store::restore_preview(&recovery[0])?)?==expected,"verified original recovery reconstructs");
 store.backup(&dir.join("current-v5.json"))?;let current:serde_json::Value=serde_json::from_slice(&fs::read(dir.join("current-v5.json"))?)?;ensure!(current["format"]=="sarv-accounting-backup-v5","newv5backupformat");let mut fresh=Store::open(&dir.join("fresh"))?;fresh.restore(Store::restore_preview(&recovery[0])?)?;ensure!(serde_json::to_value(&fresh.state)?==expected,"freshv4recoveryrestoreexact");drop(fresh);ensure!(serde_json::to_value(Store::open(&dir.join("fresh"))?.state)?==expected,"freshrestoredreopenexact");drop(store);let reopened=Store::open(&dir)?;ensure!(reopened.local_generation()==72&&serde_json::to_value(&reopened.state)?==expected,"upgradeidempotentreopen");ensure!(fs::read_dir(&dir)?.filter(|x|x.as_ref().unwrap().file_name().to_string_lossy().starts_with("before-schema5-")).count()==1,"no repeated recovery");let db=rusqlite::Connection::open(dir.join("sarv.sqlite3"))?;let integrity:String=db.query_row("pragma integrity_check",[],|r|r.get(0))?;ensure!(integrity=="ok","integrity");
 let report=serde_json::json!({"result":"passed","source":source,"schema_before":4,"schema_after":5,"generation_before":71,"generation_after":72,"quotes":prior.quotes.len(),"journals":prior.accounting.journals.len(),"opening_records":prior.accounting.core.openings.len(),"zero_aliases":prior.accounting.core.zero_requests.len(),"all_prior_state_exact_except_schema":true,"quote_csv_byte_exact":true,"procurement_default_empty":true,"original_v4_recovery_exact":true,"fresh_restore_and_reopen":true,"sqlite_integrity":"ok"});fs::write(dir.join("independent-verification.json"),serde_json::to_vec_pretty(&report)?)?;println!("PASS independentactualschema4→5 {name}: exact priorfullstate/quotes/manual/M3opening/zeroaliases, originalv4recovery,v5backup,freshrestore/reopen,onegeneration");
 }Ok(())}
